function gpsControls(){
 const pending=gpsFeedback.status==='pending';
 const failed=gpsFeedback.status==='error';
 return `<div id="gps-controls"><button class="secondary block" data-action="gps" ${pending?'disabled':''}>⌖ ${pending?'Finding your location…':failed?'Retry current location':'Use my current location'}</button><div id="gps-status" class="${failed?'error':'phone-hint'}" role="${failed?'alert':'status'}" aria-live="polite">${esc(gpsFeedback.message)}</div>${pending?'<button class="text-button" data-action="cancel-gps">Cancel location request</button>':''}${failed?'<p class="location-help">If this preview cannot show a location prompt, open the <a href="https://civic-relay-vinay-1019.animalargovindan.chatgpt.site" target="_blank" rel="noopener noreferrer">demo link ↗</a> in Safari or Chrome. On Mac, check System Settings → Privacy &amp; Security → Location Services for your browser.</p>':''}</div>`;
}
function updateGpsControls(){
 const el=$('#gps-controls');if(!el)return;
 el.outerHTML=gpsControls();
 $('[data-action="gps"]').onclick=gps;
 $('[data-action="cancel-gps"]')?.addEventListener('click',()=>{cancelGps();updateGpsControls();});
}
function cancelGps(){
 if(cancelGpsRequest){cancelGpsRequest();cancelGpsRequest=null;}
 gpsFeedback={status:'idle',message:''};
}
function gps(){
 if(gpsFeedback.status==='pending')return;
 capture();cancelGps();
 const targetDraft=draft;
 gpsFeedback={status:'pending',message:'Allow location in the permission prompt. This request stops after 15 seconds.'};
 updateGpsControls();
 cancelGpsRequest=requestLocation({
  onSuccess:position=>{
   cancelGpsRequest=null;
   if(draft!==targetDraft||view!=='resident'||screen!=='new'||step!==2)return;
   // Cancellation on coordinate edits, preset selection, or navigation prevents
   // late callbacks from replacing a location the resident has already chosen.
   draft.lat=Number(position.lat.toFixed(6));draft.lng=Number(position.lng.toFixed(6));
   draft.location='Current location';draft.duplicate=null;
   gpsFeedback={status:'success',message:`Location selected${position.accuracy===null?'':` (accuracy about ${Math.round(position.accuracy)} m)`}. Check the coordinates before continuing.`};
   render();
  },
  onError:failure=>{
   cancelGpsRequest=null;
   if(draft!==targetDraft||view!=='resident'||screen!=='new'||step!==2)return;
   gpsFeedback={status:'error',message:failure.message};
   updateGpsControls();
  }
 });
}
